// 参考解：用一个数组 + 长度变量模拟顺序表
#include <iostream>
using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;
    int a[105];
    for (int i = 0; i < n; i++) cin >> a[i];
    int pos, x;
    cin >> pos >> x;

    if (pos < 1 || pos > n + 1) {
        cout << "error\n";
        return 0;
    }
    for (int j = n; j >= pos; j--) {   // 从后往前挪，腾出下标 pos-1
        a[j] = a[j - 1];
    }
    a[pos - 1] = x;
    n++;

    for (int i = 0; i < n; i++) {
        cout << a[i] << (i + 1 == n ? '\n' : ' ');
    }
    return 0;
}
